={
  "model": "pixtral-12b-2409",
  "messages": [
    {
      "role": "user",
      "content": [
        {
          "type": "text",
          "text": "Extrais TOUS les tableaux de cette image/document. Pour chaque tableau, fournis un JSON structuré avec:\n- id: numéro du tableau\n- headers: liste des en-têtes de colonnes\n- rows: liste des lignes (chaque ligne est une liste de valeurs)\n- confidence: score de confiance (0-1)\n\nRéponds UNIQUEMENT en JSON valide avec cette structure:\n{\n  \"tables\": [\n    {\n      \"id\": 1,\n      \"headers\": [...],\n      \"rows\": [[...], [...], ...],\n      \"confidence\": 0.95\n    }\n  ],\n  \"table_count\": 1\n}\n\nSi aucun tableau n'est trouvé, retourne: {\"tables\": [], \"table_count\": 0}"
        },
        {
          "type": "image_url",
          "image_url": {
            "url": "{{ $json.body.source === 'base64' ? 'data:image/png;base64,' + $json.body.data : $json.body.data }}"
          }
        }
      ]
    }
  ],
  "max_tokens": 4096,
  "temperature": 0.1
}

parameters.jsCode:
const items = $input.all();
const webhookData = $('Webhook').first().json;
const startTime = Date.now();

const results = items.map(item => {
  // Check for API errors
  if (item.json.error) {
    return {
      json: {
        success: false,
        error: {
          code: item.json.error.code || 500,
          message: item.json.error.message || 'Mistral API error',
          status: 'API_ERROR'
        },
        meta: {
          provider: 'mistral-ocr',
          execution_mode: webhookData.body.execution_mode || 'online'
        }
      }
    };
  }

  try {
    const content = item.json.choices?.[0]?.message?.content || '{}';
    // Try to extract JSON from the response
    let parsed;
    const jsonMatch = content.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      parsed = JSON.parse(jsonMatch[0]);
    } else {
      parsed = { tables: [], table_count: 0 };
    }

    // Generate markdown representation
    let rawMarkdown = '';
    if (parsed.tables && parsed.tables.length > 0) {
      parsed.tables.forEach((table, idx) => {
        if (idx > 0) rawMarkdown += '\n\n';
        // Header
        if (table.headers && table.headers.length > 0) {
          rawMarkdown += '| ' + table.headers.join(' | ') + ' |\n';
          rawMarkdown += '|' + table.headers.map(() => '---').join('|') + '|\n';
        }
        // Rows
        if (table.rows) {
          table.rows.forEach(row => {
            rawMarkdown += '| ' + row.join(' | ') + ' |\n';
          });
        }
      });
    }

    return {
      json: {
        success: true,
        data: {
          tables: parsed.tables || [],
          raw_markdown: rawMarkdown || null,
          table_count: parsed.table_count || parsed.tables?.length || 0
        },
        meta: {
          provider: 'mistral-ocr',
          model: 'pixtral-12b-2409',
          execution_mode: webhookData.body.execution_mode || 'online',
          timings: {
            ocr_ms: Date.now() - startTime,
            parse_ms: 10
          }
        }
      }
    };
  } catch (e) {
    return {
      json: {
        success: false,
        error: {
          code: 500,
          message: 'Failed to parse OCR response: ' + e.message,
          status: 'PARSE_ERROR'
        },
        meta: {
          provider: 'mistral-ocr',
          execution_mode: webhookData.body.execution_mode || 'online'
        }
      }
    };
  }
});

return results;
